-- Lot 225 : payloads 721 a 750 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-097","moteur":"chatgpt","payload":"[RaccourcIA — /portalworld]\n\nMISSION\nOuvrir un portail spectaculaire dans une scène. Un portail avec profondeur, bords lumineux et lumière réciproque entre les mondes. Préserve la scène d’origine autour du passage.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portail vers un autre monde » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Un portail avec profondeur, bords lumineux et lumière réciproque entre les mondes. Préserve la scène d’origine autour du passage. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"17d42b6d733f3f710c25f6c510f309ac73bb946e8dfd6b8e1251b5d4569ead2e"},{"ref":"RCI-IMG-097","moteur":"claude","payload":"[RaccourcIA — /portalworld]\n\nMISSION\nOuvrir un portail spectaculaire dans une scène. Un portail avec profondeur, bords lumineux et lumière réciproque entre les mondes. Préserve la scène d’origine autour du passage.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portail vers un autre monde » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Un portail avec profondeur, bords lumineux et lumière réciproque entre les mondes. Préserve la scène d’origine autour du passage. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"81f286d2fb16d091aa133eb71aabedcc165dc06ffcea046c79ddad674469b312"},{"ref":"RCI-IMG-097","moteur":"gemini","payload":"[RaccourcIA — /portalworld]\n\nMISSION\nOuvrir un portail spectaculaire dans une scène. Un portail avec profondeur, bords lumineux et lumière réciproque entre les mondes. Préserve la scène d’origine autour du passage.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portail vers un autre monde » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Un portail avec profondeur, bords lumineux et lumière réciproque entre les mondes. Préserve la scène d’origine autour du passage. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"c0d4f039b7a86f5e143760efefc9ae6b72f3b9c348c4ebd721de3bb41df71150"},{"ref":"RCI-IMG-098","moteur":"chatgpt","payload":"[RaccourcIA — /timeslice]\n\nMISSION\nMontrer plusieurs instants d'un mouvement dans une seule image. Trois à cinq positions successives dans un décor stable, ordre temporel lisible et corps distincts. Ce sont des phases, pas des membres supplémentaires fusionnés.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le su